package org.apache.commons.math3.complex;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Math_5_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        Complex zeroComplex = new Complex(0.0, 0.0);
        Complex result = zeroComplex.reciprocal();
        assertEquals("Reciprocal of zero complex should be infinity", Complex.INF, result);
    }
}

